CREATE TYPE "tipo_movimentacao" AS ENUM (
  'Pix',
  'Debito',
  'Credito',
  'Dinheiro',
  'Reserva'
);

CREATE TABLE "conta" (
  "id_conta" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "banco_conta" varchar NOT NULL
);

CREATE TABLE "movimentacao" (
  "id_conta" int NOT NULL,
  "id_movimentacao" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_codigomovimentacao" varchar NOT NULL,
  "tipo_movimentacao" tipo_movimentacao NOT NULL,
  "descricao_movimentacao" varchar NOT NULL,
  "valor_movimentacao" decimal(8,2) NOT NULL,
  "data_movimentacao" date NOT NULL,
  "parcelaatual_movimentacao" int,
  "parcelatotal_movimentacao" int,
  "id_categoria" int
);

CREATE TABLE "categoria" (
  "id_categoria" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome_categoria" varchar NOT NULL
);

CREATE UNIQUE INDEX ON "movimentacao" ("id_codigomovimentacao", "id_conta");

CREATE UNIQUE INDEX ON "categoria" ("nome_categoria");

ALTER TABLE "movimentacao" ADD FOREIGN KEY ("id_conta") REFERENCES "conta" ("id_conta") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "movimentacao" ADD FOREIGN KEY ("id_categoria") REFERENCES "categoria" ("id_categoria") DEFERRABLE INITIALLY IMMEDIATE;
